import{_ as a,o as i,c as s,a0 as e}from"./chunks/framework.CShDTZbC.js";const g=JSON.parse('{"title":"웹 UI","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/webui.md","filePath":"ko/guide/webui.md"}'),r={name:"ko/guide/webui.md"};function d(n,t,l,o,h,p){return i(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="웹-ui" tabindex="-1">웹 UI <a class="header-anchor" href="#웹-ui" aria-label="Permalink to &quot;웹 UI&quot;">​</a></h1><p>AirlineSim Autobuy는 Vue 3 + Vite로 구축된 웹 관리 인터페이스를 Go 바이너리에 내장하고 있습니다. 브라우저를 통해 엔진을 제어하고, 규칙을 관리하며, 실시간 로그를 확인할 수 있습니다.</p><h2 id="접속" tabindex="-1">접속 <a class="header-anchor" href="#접속" aria-label="Permalink to &quot;접속&quot;">​</a></h2><p>기본 설정에서 Web UI는 <code>http://localhost:9090</code>에서 접속할 수 있습니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 기본 주소</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">http://localhost:9090</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 원격 접속 (host가 0.0.0.0인 경우)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">http://your-server-ip:9090</span></span></code></pre></div><h2 id="대시보드-dashboard" tabindex="-1">대시보드 (Dashboard) <a class="header-anchor" href="#대시보드-dashboard" aria-label="Permalink to &quot;대시보드 (Dashboard)&quot;">​</a></h2><p>대시보드는 엔진의 전반적인 상태를 한눈에 보여줍니다.</p><h3 id="엔진-상태-배너" tabindex="-1">엔진 상태 배너 <a class="header-anchor" href="#엔진-상태-배너" aria-label="Permalink to &quot;엔진 상태 배너&quot;">​</a></h3><ul><li><strong>Running</strong>: 엔진이 실행 중이며 시장을 모니터링하고 있습니다.</li><li><strong>Stopped</strong>: 엔진이 중지된 상태입니다.</li></ul><h3 id="엔진-제어-버튼" tabindex="-1">엔진 제어 버튼 <a class="header-anchor" href="#엔진-제어-버튼" aria-label="Permalink to &quot;엔진 제어 버튼&quot;">​</a></h3><table tabindex="0"><thead><tr><th>버튼</th><th>동작</th></tr></thead><tbody><tr><td><strong>Start Engine</strong></td><td>모니터링 엔진 시작</td></tr><tr><td><strong>Stop Engine</strong></td><td>모니터링 엔진 중지</td></tr></tbody></table><h3 id="통계-카드" tabindex="-1">통계 카드 <a class="header-anchor" href="#통계-카드" aria-label="Permalink to &quot;통계 카드&quot;">​</a></h3><table tabindex="0"><thead><tr><th>메트릭</th><th>설명</th></tr></thead><tbody><tr><td><strong>Market Scans</strong></td><td>수행된 시장 스캔 횟수</td></tr><tr><td><strong>Aircraft Found</strong></td><td>규칙에 일치하는 항공기 발견 수</td></tr><tr><td><strong>Purchased</strong></td><td>성공적으로 구매한 항공기 수</td></tr><tr><td><strong>Failed</strong></td><td>실패한 구매 시도 수</td></tr></tbody></table><h3 id="기타-정보" tabindex="-1">기타 정보 <a class="header-anchor" href="#기타-정보" aria-label="Permalink to &quot;기타 정보&quot;">​</a></h3><ul><li><strong>Last Engine Error</strong>: 마지막 엔진 오류 메시지</li><li><strong>Activity</strong>: 마지막 스캔 시간</li></ul><p>대시보드는 3초마다 자동으로 상태를 갱신합니다.</p><h2 id="규칙-페이지-rules" tabindex="-1">규칙 페이지 (Rules) <a class="header-anchor" href="#규칙-페이지-rules" aria-label="Permalink to &quot;규칙 페이지 (Rules)&quot;">​</a></h2><p>규칙 페이지에서는 구매 규칙을 생성, 수정, 삭제, 활성화/비활성화할 수 있습니다.</p><h3 id="규칙-목록" tabindex="-1">규칙 목록 <a class="header-anchor" href="#규칙-목록" aria-label="Permalink to &quot;규칙 목록&quot;">​</a></h3><p>각 규칙은 카드 형태로 표시되며 다음 정보를 포함합니다:</p><ul><li><strong>규칙 이름</strong> 및 메타 정보 (우선순위, 항공기 유형)</li><li><strong>활성/비활성</strong> 배지</li><li><strong>규칙 상세 정보</strong>: 가격 범위, 최대 기령, 최소 상태, 최대 사이클, 자동 구매 상태, 스내치 상태</li></ul><h3 id="규칙-작업" tabindex="-1">규칙 작업 <a class="header-anchor" href="#규칙-작업" aria-label="Permalink to &quot;규칙 작업&quot;">​</a></h3><table tabindex="0"><thead><tr><th>작업</th><th>설명</th></tr></thead><tbody><tr><td><strong>토글 버튼</strong> (✓)</td><td>규칙 활성화/비활성화 전환</td></tr><tr><td><strong>편집 버튼</strong> (연필 아이콘)</td><td>규칙 수정 모달 열기</td></tr><tr><td><strong>삭제 버튼</strong> (휴지통 아이콘)</td><td>규칙 삭제 (확인 후 실행)</td></tr><tr><td><strong>New Rule</strong> 버튼</td><td>새 규칙 생성 모달 열기</td></tr></tbody></table><h3 id="규칙-생성-편집-폼" tabindex="-1">규칙 생성/편집 폼 <a class="header-anchor" href="#규칙-생성-편집-폼" aria-label="Permalink to &quot;규칙 생성/편집 폼&quot;">​</a></h3><p><strong>기본 정보:</strong></p><ul><li><strong>Rule Name</strong>: 규칙 이름 (필수)</li><li><strong>Server</strong>: 대상 서버 선택</li><li><strong>Account</strong>: 사용할 계정 선택</li></ul><p><strong>항공기 조건:</strong></p><ul><li><strong>Aircraft Family</strong>: 항공기 패밀리 선택</li><li><strong>Aircraft Type</strong>: 특정 항공기 유형 선택</li><li><strong>Sort By</strong>: 시장 정렬 기준</li></ul><p><strong>가격 및 상태 조건:</strong></p><ul><li><strong>Min / Max Price</strong>: 가격 범위 (AS$)</li><li><strong>Max Age</strong>: 최대 기령 (년)</li><li><strong>Max Cycles</strong>: 최대 사이클</li><li><strong>Min Condition</strong>: 최소 상태 (%)</li></ul><p><strong>옵션:</strong></p><ul><li><strong>Offer Types</strong>: 제공 유형 선택 (Auction, Immediate)</li><li><strong>Financing Options</strong>: 금융 옵션 선택 (Cash, Credit, Lease)</li></ul><p><strong>작업 설정:</strong></p><ul><li><strong>Priority</strong>: 규칙 우선순위</li><li><strong>Max Bid Increment</strong>: 최대 입찰 증가액 (AS$)</li><li><strong>Enabled</strong>: 규칙 활성화</li><li><strong>Auto Buy</strong>: 자동 구매 활성화</li><li><strong>Snatch</strong>: 스내치 모드 활성화</li></ul><h2 id="설정-페이지-settings" tabindex="-1">설정 페이지 (Settings) <a class="header-anchor" href="#설정-페이지-settings" aria-label="Permalink to &quot;설정 페이지 (Settings)&quot;">​</a></h2><p>설정 페이지에서는 애플리케이션의 전역 설정을 관리할 수 있습니다.</p><h3 id="서버-연결" tabindex="-1">서버 연결 <a class="header-anchor" href="#서버-연결" aria-label="Permalink to &quot;서버 연결&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">servers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">free1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://free1.airlinesim.aero</span></span></code></pre></div><ul><li><strong>+ Add Server</strong> 버튼으로 새 서버 추가</li><li>각 서버의 <code>host</code>와 <code>base_url</code> 설정</li><li>서버 삭제 버튼 (2개 이상일 때 활성화)</li></ul><h3 id="인증-계정" tabindex="-1">인증 계정 <a class="header-anchor" href="#인증-계정" aria-label="Permalink to &quot;인증 계정&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">username</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">account@example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    session_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">session.json</span></span></code></pre></div><ul><li><strong>+ Add Account</strong> 버튼으로 새 계정 추가</li><li>각 계정의 사용자명, 비밀번호 설정</li><li>세션 파일은 자동으로 관리됩니다</li></ul><h3 id="모니터링-설정" tabindex="-1">모니터링 설정 <a class="header-anchor" href="#모니터링-설정" aria-label="Permalink to &quot;모니터링 설정&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><strong>Poll Interval</strong></td><td>서버 스캔 간격 (초, 최소 15)</td></tr><tr><td><strong>Jitter</strong></td><td>무작위 지연 시간 (초)</td></tr><tr><td><strong>Request Timeout</strong></td><td>HTTP 요청 타임아웃 (초)</td></tr><tr><td><strong>Minimum Account Balance</strong></td><td>구매 후 최소 유지 잔액 (AS$)</td></tr></tbody></table><h3 id="알림-설정" tabindex="-1">알림 설정 <a class="header-anchor" href="#알림-설정" aria-label="Permalink to &quot;알림 설정&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><strong>Console Output</strong></td><td>콘솔 알림 활성화/비활성화</td></tr><tr><td><strong>Discord Webhook</strong></td><td>Discord 웹훅 URL (선택 사항)</td></tr></tbody></table><h3 id="web-ui-설정" tabindex="-1">Web UI 설정 <a class="header-anchor" href="#web-ui-설정" aria-label="Permalink to &quot;Web UI 설정&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><strong>Host</strong></td><td>웹 서버 바인딩 주소</td></tr><tr><td><strong>Port</strong></td><td>웹 서버 포트</td></tr></tbody></table><h3 id="저장" tabindex="-1">저장 <a class="header-anchor" href="#저장" aria-label="Permalink to &quot;저장&quot;">​</a></h3><p>설정을 변경한 후 <strong>Save Settings</strong> 버튼을 클릭하면 설정 파일에 저장되고 엔진이 자동으로 리로드됩니다.</p><h2 id="로그-페이지-logs" tabindex="-1">로그 페이지 (Logs) <a class="header-anchor" href="#로그-페이지-logs" aria-label="Permalink to &quot;로그 페이지 (Logs)&quot;">​</a></h2><p>로그 페이지는 엔진의 실시간 활동 로그를 제공합니다.</p><h3 id="기능" tabindex="-1">기능 <a class="header-anchor" href="#기능" aria-label="Permalink to &quot;기능&quot;">​</a></h3><ul><li><strong>실시간 로그 스트리밍</strong>: Server-Sent Events (SSE)를 통한 실시간 로그 수신</li><li><strong>로그 필터링</strong>: 키워드로 로그 필터링</li><li><strong>자동 스크롤</strong>: 새 로그 자동 스크롤 (토글 가능)</li><li><strong>로그 지우기</strong>: Clear 버튼으로 로그 초기화</li><li><strong>최대 1000개 항목</strong>: 로그는 최대 1000개까지 유지되며 초과 시 오래된 항목부터 제거됩니다</li></ul><h3 id="로그-색상" tabindex="-1">로그 색상 <a class="header-anchor" href="#로그-색상" aria-label="Permalink to &quot;로그 색상&quot;">​</a></h3><table tabindex="0"><thead><tr><th>로그 레벨</th><th>색상</th></tr></thead><tbody><tr><td>ERROR</td><td>빨간색</td></tr><tr><td>WARN</td><td>노란색</td></tr><tr><td>INFO</td><td>기본 색상</td></tr></tbody></table><h2 id="api-엔드포인트" tabindex="-1">API 엔드포인트 <a class="header-anchor" href="#api-엔드포인트" aria-label="Permalink to &quot;API 엔드포인트&quot;">​</a></h2><p>Web UI는 다음 REST API 엔드포인트를 제공합니다:</p><h3 id="상태-및-제어" tabindex="-1">상태 및 제어 <a class="header-anchor" href="#상태-및-제어" aria-label="Permalink to &quot;상태 및 제어&quot;">​</a></h3><table tabindex="0"><thead><tr><th>메서드</th><th>엔드포인트</th><th>설명</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/status</code></td><td>엔진 상태 조회</td></tr><tr><td>POST</td><td><code>/api/control/start</code></td><td>엔진 시작</td></tr><tr><td>POST</td><td><code>/api/control/stop</code></td><td>엔진 중지</td></tr><tr><td>POST</td><td><code>/api/reload</code></td><td>규칙 리로드</td></tr></tbody></table><h3 id="설정" tabindex="-1">설정 <a class="header-anchor" href="#설정" aria-label="Permalink to &quot;설정&quot;">​</a></h3><table tabindex="0"><thead><tr><th>메서드</th><th>엔드포인트</th><th>설명</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/config</code></td><td>설정 조회</td></tr><tr><td>PUT</td><td><code>/api/config</code></td><td>설정 업데이트</td></tr></tbody></table><h3 id="규칙-관리" tabindex="-1">규칙 관리 <a class="header-anchor" href="#규칙-관리" aria-label="Permalink to &quot;규칙 관리&quot;">​</a></h3><table tabindex="0"><thead><tr><th>메서드</th><th>엔드포인트</th><th>설명</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/rules</code></td><td>규칙 목록 조회</td></tr><tr><td>POST</td><td><code>/api/rules</code></td><td>새 규칙 생성</td></tr><tr><td>GET</td><td><code>/api/rules/{id}</code></td><td>특정 규칙 조회</td></tr><tr><td>PUT</td><td><code>/api/rules/{id}</code></td><td>특정 규칙 수정</td></tr><tr><td>DELETE</td><td><code>/api/rules/{id}</code></td><td>특정 규칙 삭제</td></tr><tr><td>PATCH</td><td><code>/api/rules/{id}/toggle</code></td><td>규칙 활성화 전환</td></tr><tr><td>PUT</td><td><code>/api/rules/reorder</code></td><td>규칙 순서 변경</td></tr></tbody></table><h3 id="데이터" tabindex="-1">데이터 <a class="header-anchor" href="#데이터" aria-label="Permalink to &quot;데이터&quot;">​</a></h3><table tabindex="0"><thead><tr><th>메서드</th><th>엔드포인트</th><th>설명</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/aircraft-data</code></td><td>항공기 데이터 (패밀리, 유형) 조회</td></tr></tbody></table><h2 id="프론트엔드-개발" tabindex="-1">프론트엔드 개발 <a class="header-anchor" href="#프론트엔드-개발" aria-label="Permalink to &quot;프론트엔드 개발&quot;">​</a></h2><p>프론트엔드는 <code>internal/webui/frontend/</code> 디렉토리에 위치하며, Vue 3 + TypeScript로 작성되었습니다.</p><h3 id="개발-서버-실행" tabindex="-1">개발 서버 실행 <a class="header-anchor" href="#개발-서버-실행" aria-label="Permalink to &quot;개발 서버 실행&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> internal/webui/frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>개발 서버는 <code>http://localhost:5173</code>에서 실행되며, API 요청은 Go 백엔드(<code>localhost:9090</code>)로 프록시됩니다. CORS는 개발 모드에서 자동으로 처리됩니다.</p><h3 id="프로덕션-빌드" tabindex="-1">프로덕션 빌드 <a class="header-anchor" href="#프로덕션-빌드" aria-label="Permalink to &quot;프로덕션 빌드&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-build</span></span></code></pre></div><p>빌드된 파일은 <code>internal/webui/frontend/dist/</code>에 생성되며, Go 바이너리에 내장됩니다.</p><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><a href="/ko/reference/api.html">API 참조</a> - 모든 REST API 엔드포인트 상세</li><li><a href="/ko/guide/configuration.html">설정 가이드</a> - Web UI 설정 옵션</li><li><a href="/ko/guide/quickstart.html">빠른 시작</a> - 설치 및 실행</li></ul>`,76)])])}const u=a(r,[["render",d]]);export{g as __pageData,u as default};
